1	import { SnapshotFailure, StorageDefect } from '@omne-harness-lite/storage'
2	
3	export function physicalFailure(error: unknown): unknown {
4	  if (error instanceof SnapshotFailure || error instanceof StorageDefect) return error
5	  if (error instanceof Error && 'errcode' in error && typeof error.errcode === 'number') {
6	    const primary = error.errcode & 0xff
7	    if (primary === 11 || primary === 26)
8	      return new SnapshotFailure('invalid-data', { cause: error })
9	    if (primary === 13) return new SnapshotFailure('capacity', { cause: error })
10	    if ([5, 6, 7, 10, 14].includes(primary))
11	      return new SnapshotFailure('unavailable', { cause: error })
12	  }
13	  if (
14	    error instanceof Error &&
15	    'code' in error &&
16	    typeof error.code === 'string' &&
17	    ['ENOENT', 'EACCES', 'EPERM', 'EIO', 'ENOMEM', 'EBADF', 'EBUSY', 'EROFS', 'EEXIST'].includes(
18	      error.code,
19	    )
20	  )
21	    return new SnapshotFailure('unavailable', { cause: error })
22	  if (error instanceof Error && 'code' in error && error.code === 'ENOSPC')
23	    return new SnapshotFailure('capacity', { cause: error })
24	  return error
25	}
26	
27	/** Cleanup can replace an ordinary refusal, but must never erase an internal defect. */
28	export function combineFailure(primary: unknown, cleanup: unknown): unknown {
29	  if (primary === cleanup) return primary
30	  const first = physicalFailure(primary)
31	  const second = physicalFailure(cleanup)
32	  if (first instanceof SnapshotFailure && second instanceof SnapshotFailure) return second
33	  return new AggregateError([first, second], 'maintenance operation and cleanup failed')
34	}
35	
36	/** Both branches settle before their owner can release resources. */
37	export async function withCleanup<T>(
38	  work: () => Promise<T>,
39	  cleanup: () => Promise<void>,
40	): Promise<T> {
41	  let outcome: { ok: true; value: T } | { ok: false; error: unknown }
42	  try {
43	    outcome = { ok: true, value: await work() }
44	  } catch (error) {
45	    outcome = { ok: false, error }
46	  }
47	  try {
48	    await cleanup()
49	  } catch (error) {
50	    throw outcome.ok ? error : combineFailure(outcome.error, error)
51	  }
52	  if (!outcome.ok) throw outcome.error
53	  return outcome.value
54	}
