1	import {
2	  SnapshotFailure,
3	  StorageDefect,
4	  type SnapshotInspectionSession,
5	} from '@omne-harness-lite/storage'
6	import { maintenanceFailure, MaintenanceFailure } from './failure.ts'
7	
8	export function cleanupFailure(error: unknown, location: string): unknown {
9	  const residual = new SnapshotFailure('unavailable', { cause: error, residual: location })
10	  if (maintenanceFailure(error) instanceof MaintenanceFailure) return residual
11	  return new AggregateError([error, residual], 'maintenance resource cleanup failed')
12	}
13	
14	/** Local resource location accompanies cleanup failures, without exposing contents. */
15	export function ownResourceAt(
16	  session: SnapshotInspectionSession,
17	  close: () => void | Promise<void>,
18	  isClosed: () => boolean,
19	  location: string,
20	): () => Promise<void> {
21	  return session.ownResource(async () => {
22	    try {
23	      await close()
24	      if (!isClosed()) throw new StorageDefect('maintenance resource remains open after close')
25	    } catch (error) {
26	      throw cleanupFailure(error, location)
27	    }
28	  }, isClosed)
29	}
