1	import type { DatabaseSync } from 'node:sqlite'
2	import {
3	  Kysely,
4	  SqliteAdapter,
5	  SqliteIntrospector,
6	  SqliteQueryCompiler,
7	  type DatabaseConnection,
8	  type Driver,
9	} from 'kysely'
10	import { StorageDefect, type UntypedDb } from '@omne-harness-lite/storage'
11	import { NodeSqliteConnection } from '../sqlite/driver.ts'
12	import { UniqueConstraintResolver } from '../sqlite/constraints.ts'
13	
14	/** Borrows an already-owned read-only handle, never opens a path or closes its owner. */
15	class SnapshotReadDriver implements Driver {
16	  readonly #connection: DatabaseConnection
17	  #queue: Promise<void> = Promise.resolve()
18	  #release: (() => void) | undefined
19	  #closed = false
20	  constructor(handle: DatabaseSync) {
21	    this.#connection = new NodeSqliteConnection(handle, 'read', new UniqueConstraintResolver())
22	  }
23	  async init(): Promise<void> {}
24	  async acquireConnection(): Promise<DatabaseConnection> {
25	    if (this.#closed) throw new StorageDefect('snapshot view has ended')
26	    const previous = this.#queue
27	    let release!: () => void
28	    this.#queue = new Promise<void>(resolve => {
29	      release = resolve
30	    })
31	    await previous
32	    if (this.#closed) {
33	      release()
34	      throw new StorageDefect('snapshot view has ended')
35	    }
36	    this.#release = release
37	    return this.#connection
38	  }
39	  async releaseConnection(): Promise<void> {
40	    const release = this.#release
41	    this.#release = undefined
42	    release?.()
43	  }
44	  async beginTransaction(): Promise<void> {
45	    throw new StorageDefect('snapshot already owns its read transaction')
46	  }
47	  async commitTransaction(): Promise<void> {
48	    throw new StorageDefect('snapshot owns transaction completion')
49	  }
50	  async rollbackTransaction(): Promise<void> {
51	    throw new StorageDefect('snapshot owns transaction completion')
52	  }
53	  async destroy(): Promise<void> {
54	    this.#closed = true
55	    await this.#queue
56	  }
57	}
58	
59	export function snapshotReadDb(handle: DatabaseSync): UntypedDb {
60	  const driver = new SnapshotReadDriver(handle)
61	  return new Kysely({
62	    dialect: {
63	      createDriver: () => driver,
64	      createAdapter: () => new SqliteAdapter(),
65	      createQueryCompiler: () => new SqliteQueryCompiler(),
66	      createIntrospector: db => new SqliteIntrospector(db),
67	    },
68	  })
69	}
