1	import { DatabaseSync } from 'node:sqlite'
2	import { isSqliteBusy } from './errors.ts'
3	import type { OwnerLock } from '../upgrade/owner.ts'
4	
5	/** Strong references are necessary: GC must never end ownership. */
6	const heldLocks = new Set<DatabaseSync>()
7	
8	export class SqliteLockBusy extends Error {
9	  override readonly name = 'SqliteLockBusy'
10	}
11	
12	/** Private empty coordination database, never a production data connection. */
13	export function acquireSqliteLock(file: string): OwnerLock {
14	  const db = new DatabaseSync(file, { timeout: 0 })
15	  try {
16	    db.exec('PRAGMA journal_mode = MEMORY')
17	    db.exec('BEGIN IMMEDIATE')
18	  } catch (error) {
19	    db.close()
20	    if (isSqliteBusy(error)) throw new SqliteLockBusy('coordination lock is occupied')
21	    throw error
22	  }
23	  heldLocks.add(db)
24	  let released = false
25	  return {
26	    async release() {
27	      if (released) return
28	      try {
29	        if (db.isTransaction) db.exec('ROLLBACK')
30	      } finally {
31	        db.close()
32	        released = true
33	        heldLocks.delete(db)
34	      }
35	    },
36	  }
37	}
