1	// Storage 协议的实现：读、写各一个 Kysely 实例（同一底层库），锁语义按方言，撤除时关准入→等在途→关句柄。
2	import { AsyncLocalStorage } from 'node:async_hooks'
3	import type { AtomicStorage, StorageUnit } from '@omne-harness-lite/storage'
4	import { SqlStorageUnit } from './unit.ts'
5	import type { SnapshotEngine } from './maintenance/engine.ts'
6	import {
7	  SnapshotFailure,
8	  type SnapshotMaintenance,
9	  type SnapshotRunOptions,
10	  type SnapshotSession,
11	} from '@omne-harness-lite/storage'
12	import type { StorageSqlLogger } from './upgrade/owner.ts'
13	import { sql, type Kysely, type Transaction } from 'kysely'
14	import {
15	  StorageDefect,
16	  StorageUnavailable,
17	  type ReadTx,
18	  type StorageInstance,
19	  type UntypedDb,
20	  type WriteTx,
21	} from '@omne-harness-lite/storage'
22	
23	const retainedHandles = new Set<DialectHandles>()
24	/** Faulted owners retain native dependencies until process exit. */
25	export function retainStorageHandles(handles: DialectHandles): void {
26	  retainedHandles.add(handles)
27	}
28	
29	export interface DialectHandles {
30	  /** Native observation, including handles whose driver initialization failed. */
31	  readonly resourcesClosed?: () => boolean
32	  readonly readDb: UntypedDb
33	  readonly writeDb: UntypedDb
34	  /** 在写事务里对命中的行取排他锁；sqlite 下不发语句。 */
35	  lockRow(
36	    trx: Transaction<UntypedDb>,
37	    table: string,
38	    key: Readonly<Record<string, unknown>>,
39	  ): Promise<void>
40	  lockSentinel(trx: Transaction<UntypedDb>, name: string): Promise<void>
41	  /** 读事务的隔离设置（pg：REPEATABLE READ READ ONLY；sqlite：由只读句柄承担）。 */
42	  readonly readIsolation: 'repeatable read' | undefined
43	  readonly writeIsolation: 'read committed' | undefined
44	  /** 当前库里已存在的用户表名（含迁移登记表）；在调用方给的事务里读，不写。 */
45	  listTables(db: UntypedDb): Promise<string[]>
46	}
47	
48	/** 属主实例的撤除收尾，由升级守卫提供；不开守卫的实例没有这一层。 */
49	export interface StorageTeardown {
50	  /** 撤除第一步：守卫置为已撤（此后 confirm 抛 NotAttached）；返回需要等它返回的在途确认。 */
51	  begin(): Promise<unknown> | undefined
52	  /** 句柄关闭之后：磁盘上仍有快照 ⇒ 恢复（句柄没关干净则不恢复）；最后放排他。 */
53	  finish(handlesClosed: boolean): Promise<void>
54	}
55	
56	/** Created only in the owner startup path with that instance's source and attachment. */
57	export interface OwnedSnapshots {
58	  readonly engine: SnapshotEngine
59	  readonly confirmed: () => boolean
60	  readonly onClosed: (status: 'clean' | 'error') => void
61	}
62	
63	export class SqlStorage implements StorageInstance, AtomicStorage {
64	  readonly maintenance: SnapshotMaintenance | undefined
65	  /** 在途事务的异步上下文：在 fn 里再调 read/write 是嵌套调用 ⇒ StorageDefect（写队列下会自锁）。 */
66	  readonly #inTx = new AsyncLocalStorage<'read' | 'write'>()
67	  #closed = false
68	  #closing: Promise<void> | undefined
69	  #inflight = 0
70	  #drained: (() => void) | undefined
71	
72	  constructor(
73	    private readonly handles: DialectHandles,
74	    private readonly teardown?: StorageTeardown,
75	    private readonly logger?: StorageSqlLogger,
76	    private readonly snapshots?: OwnedSnapshots,
77	  ) {
78	    this.maintenance =
79	      snapshots === undefined
80	        ? undefined
81	        : {
82	            run: <T>(fn: (session: SnapshotSession) => Promise<T>, options?: SnapshotRunOptions) =>
83	              this.#maintain(fn, options),
84	          }
85	  }
86	
87	  async #maintain<T>(
88	    fn: (session: SnapshotSession) => Promise<T>,
89	    options?: SnapshotRunOptions,
90	  ): Promise<T> {
91	    if (this.snapshots === undefined || !this.snapshots.confirmed())
92	      throw new SnapshotFailure('unavailable')
93	    try {
94	      this.#admit()
95	    } catch (error) {
96	      if (error instanceof StorageUnavailable)
97	        throw new SnapshotFailure('unavailable', { cause: error })
98	      throw error
99	    }
100	    try {
101	      return await this.snapshots.engine.run(fn, options)
102	    } finally {
103	      this.#leave()
104	    }
105	  }
106	
107	  async atomic<T>(fn: (unit: StorageUnit) => Promise<T>): Promise<T> {
108	    let unit: SqlStorageUnit | undefined
109	    const result = await this.write(tx => {
110	      unit = new SqlStorageUnit(this, tx)
111	      return unit.execute(fn)
112	    })
113	    // write 已提交并退出其上下文；通知不得在事务回调内部派发。
114	    unit!.publish(() => {
115	      if (this.logger !== undefined) this.logger.error('after-commit notification failed')
116	      else console.error('storage-sql: after-commit notification failed')
117	    })
118	    return result
119	  }
120	
121	  async read<T>(fn: (tx: ReadTx) => Promise<T>): Promise<T> {
122	    this.#admit()
123	    try {
124	      let builder = this.handles.readDb.transaction().setAccessMode('read only')
125	      if (this.handles.readIsolation !== undefined)
126	        builder = builder.setIsolationLevel(this.handles.readIsolation)
127	      return await this.#inTx.run('read', () =>
128	        builder.execute(async trx => fn({ db: trx as unknown as UntypedDb })),
129	      )
130	    } finally {
131	      this.#leave()
132	    }
133	  }
134	
135	  async write<T>(fn: (tx: WriteTx) => Promise<T>): Promise<T> {
136	    this.#admit()
137	    try {
138	      let builder = this.handles.writeDb.transaction().setAccessMode('read write')
139	      if (this.handles.writeIsolation !== undefined)
140	        builder = builder.setIsolationLevel(this.handles.writeIsolation)
141	      return await this.#inTx.run('write', () =>
142	        builder.execute(async trx => {
143	          const tx: WriteTx = {
144	            db: trx as unknown as UntypedDb,
145	            lockRow: (table, key) => this.handles.lockRow(trx, table, key),
146	            lockSentinel: name => this.handles.lockSentinel(trx, name),
147	          }
148	          return fn(tx)
149	        }),
150	      )
151	    } finally {
152	      this.#leave()
153	    }
154	  }
155	
156	  /**
157	   * 关准入 → 等在途事务各自收场（与在途的升级确认）→ 关句柄 → 属主实例：恢复未确认的快照、放排他。
158	   * 之后 read/write ⇒ StorageUnavailable。重复调用得到同一次收尾。
159	   */
160	  close(): Promise<void> {
161	    this.#closing ??= this.#close()
162	    return this.#closing
163	  }
164	
165	  async #close(): Promise<void> {
166	    try {
167	      await this.#closeResources()
168	      this.snapshots?.onClosed('clean')
169	    } catch (error) {
170	      this.snapshots?.onClosed('error')
171	      throw error
172	    }
173	  }
174	
175	  async #closeResources(): Promise<void> {
176	    const confirming = this.teardown?.begin()
177	    this.#closed = true
178	    const maintenance = this.snapshots?.engine.close().then(
179	      () => ({ ok: true as const }),
180	      error => ({ ok: false as const, error: error as unknown }),
181	    )
182	    if (this.#inflight > 0) {
183	      await new Promise<void>(resolve => {
184	        this.#drained = resolve
185	      })
186	    }
187	    // 确认的失败归调用 confirm() 的那一方；这里只等它不再碰快照
188	    await confirming?.catch(() => undefined)
189	    const maintenanceResult = await maintenance
190	    if (this.snapshots !== undefined && !this.snapshots.engine.ownershipReleased) {
191	      retainStorageHandles(this.handles)
192	      throw new StorageDefect('maintenance resources remain owned; source ownership is retained', {
193	        cause: maintenanceResult?.ok === false ? maintenanceResult.error : undefined,
194	      })
195	    }
196	    let handlesClosed = false
197	    try {
198	      try {
199	        await this.handles.writeDb.destroy()
200	      } finally {
201	        await this.handles.readDb.destroy()
202	      }
203	      if (this.handles.resourcesClosed?.() === false)
204	        throw new StorageDefect('native storage handles remain open')
205	      handlesClosed = true
206	    } finally {
207	      if (this.snapshots !== undefined && !handlesClosed) {
208	        retainStorageHandles(this.handles)
209	        throw new StorageDefect('storage handles did not close; source ownership is retained')
210	      }
211	      await this.teardown?.finish(handlesClosed)
212	    }
213	    if (maintenanceResult?.ok === false) throw maintenanceResult.error
214	  }
215	
216	  #admit(): void {
217	    const enclosing = this.#inTx.getStore()
218	    if (enclosing !== undefined)
219	      throw new StorageDefect(`nested storage call inside a ${enclosing} transaction`)
220	    if (this.#closed) throw new StorageUnavailable('storage is closed')
221	    this.#inflight += 1
222	  }
223	
224	  #leave(): void {
225	    this.#inflight -= 1
226	    if (this.#inflight === 0 && this.#drained !== undefined) {
227	      const resolve = this.#drained
228	      this.#drained = undefined
229	      resolve()
230	    }
231	  }
232	}
233	
234	/** 启动 ping：连不上即抛出（启动失败，不半开）。 */
235	export async function ping(db: Kysely<unknown>): Promise<void> {
236	  await sql`SELECT 1`.execute(db)
237	}
