1	// 自写 node:sqlite Driver：一个写句柄 + 进程内写队列；读句柄独立、query_only=ON；BEGIN IMMEDIATE 忙时异步重试（P-12）。
2	// 复用 kysely 的 SqliteAdapter / SqliteQueryCompiler / SqliteIntrospector。
3	import { DatabaseSync } from 'node:sqlite'
4	import {
5	  CompiledQuery,
6	  SqliteAdapter,
7	  SqliteIntrospector,
8	  SqliteQueryCompiler,
9	  type DatabaseConnection,
10	  type Dialect,
11	  type Driver,
12	  type Kysely,
13	  type QueryResult,
14	  type TransactionSettings,
15	} from 'kysely'
16	import { StorageUnavailable } from '@omne-harness-lite/storage'
17	import { isSqliteBusy, translateSqliteError, type StatementKind } from './errors.ts'
18	import { UniqueConstraintResolver } from './constraints.ts'
19	import { assertProductionStoragePath } from './protection.ts'
20	
21	export interface NodeSqliteDialectOptions {
22	  readonly file: string
23	  /** 缺省 NORMAL；治理中心装配按 D-039 显式选 FULL。 */
24	  readonly synchronous?: 'normal' | 'full'
25	  /** 本 Kysely 实例只做读或只做写：提供者为两种事务各开一个实例，事务种类因此在构造期就定了。 */
26	  readonly role: 'write' | 'read'
27	  /** 写锁争用的总等待上限；超过 ⇒ StorageUnavailable。 */
28	  readonly writeLockTimeoutMs?: number
29	}
30	
31	const WRITE_LOCK_TIMEOUT_MS = 5000
32	/** 读句柄上限（候选常量）：峰值并发读之外的调用排队等释放，不无限开句柄。 */
33	const MAX_READERS = 4
34	const RETRY_BACKOFF_MS = [1, 2, 4, 8, 16, 32, 50] as const
35	
36	const sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms))
37	
38	function statementKind(sql: string): StatementKind {
39	  const head = sql.trimStart().slice(0, 6).toLowerCase()
40	  if (head.startsWith('select') || head.startsWith('with') || head.startsWith('pragma'))
41	    return 'select'
42	  if (head.startsWith('insert')) return 'insert'
43	  if (head.startsWith('update')) return 'update'
44	  if (head.startsWith('delete')) return 'delete'
45	  return 'other'
46	}
47	
48	function returnsRows(sql: string): boolean {
49	  const head = sql.trimStart().toLowerCase()
50	  return (
51	    head.startsWith('select') ||
52	    head.startsWith('with') ||
53	    head.startsWith('pragma') ||
54	    / returning /i.test(sql)
55	  )
56	}
57	
58	/** Internal reusable executor; not exported through the package's public entry. */
59	export class NodeSqliteConnection implements DatabaseConnection {
60	  constructor(
61	    readonly db: DatabaseSync,
62	    readonly role: 'write' | 'read',
63	    private readonly resolver: UniqueConstraintResolver,
64	  ) {}
65	
66	  async executeQuery<R>(compiled: CompiledQuery): Promise<QueryResult<R>> {
67	    const kind = statementKind(compiled.sql)
68	    try {
69	      const statement = this.db.prepare(compiled.sql)
70	      const parameters = compiled.parameters as readonly (
71	        null | number | bigint | string | Uint8Array
72	      )[]
73	      if (returnsRows(compiled.sql)) {
74	        const rows = statement.all(...parameters) as R[]
75	        return { rows }
76	      }
77	      const result = statement.run(...parameters)
78	      return {
79	        rows: [],
80	        numAffectedRows: BigInt(result.changes),
81	        insertId: BigInt(result.lastInsertRowid),
82	      }
83	    } catch (error) {
84	      throw translateSqliteError(
85	        error,
86	        kind,
87	        message => this.resolver.resolve(this.db, message),
88	        this.role,
89	      )
90	    }
91	  }
92	
93	  // eslint-disable-next-line require-yield
94	  async *streamQuery<R>(): AsyncIterableIterator<QueryResult<R>> {
95	    throw new Error(
96	      'streamQuery is not supported by the node:sqlite driver (the storage protocol has no streaming read face)',
97	    )
98	  }
99	}
100	
101	// Covers failed initialization before a connection can enter the pool.
102	const retainedNativeHandles = new Set<DatabaseSync>()
103	
104	export class NodeSqliteDriver implements Driver {
105	  readonly #native = new Set<DatabaseSync>()
106	  get resourcesClosed(): boolean {
107	    return [...this.#native].every(db => !db.isOpen)
108	  }
109	  #writer: NodeSqliteConnection | undefined
110	  #readers: NodeSqliteConnection[] = []
111	  #openReaders = 0
112	  #readerWaiters: ((c: DatabaseConnection) => void)[] = []
113	  #writeQueue: Promise<void> = Promise.resolve()
114	  #closed = false
115	  readonly #resolver = new UniqueConstraintResolver()
116	
117	  constructor(private readonly options: NodeSqliteDialectOptions) {}
118	
119	  async init(): Promise<void> {
120	    if (this.options.role === 'write') {
121	      this.#writer = new NodeSqliteConnection(this.#open('write'), 'write', this.#resolver)
122	    } else {
123	      // 读句柄按需开；这里开一个以便打开失败在启动期暴露
124	      this.#readers.push(new NodeSqliteConnection(this.#open('read'), 'read', this.#resolver))
125	      this.#openReaders = 1
126	    }
127	  }
128	
129	  #open(role: 'write' | 'read'): DatabaseSync {
130	    assertProductionStoragePath(this.options.file)
131	    const db = new DatabaseSync(this.options.file, {
132	      enableForeignKeyConstraints: true,
133	      timeout: role === 'write' ? 0 : 5000,
134	    })
135	    this.#native.add(db)
136	    try {
137	      db.exec('PRAGMA journal_mode = WAL')
138	      db.exec(
139	        this.options.synchronous === 'full'
140	          ? 'PRAGMA synchronous = FULL'
141	          : 'PRAGMA synchronous = NORMAL',
142	      )
143	      db.exec('PRAGMA foreign_keys = ON')
144	      if (role === 'read') db.exec('PRAGMA query_only = ON')
145	      return db
146	    } catch (error) {
147	      // The pool does not own this handle until initialization succeeds.
148	      try {
149	        db.close()
150	      } catch (closing) {
151	        if (db.isOpen) retainedNativeHandles.add(db)
152	        throw new AggregateError([error, closing], 'sqlite initialization and cleanup failed')
153	      }
154	      throw error
155	    }
156	  }
157	
158	  async acquireConnection(): Promise<DatabaseConnection> {
159	    if (this.#closed) throw new StorageUnavailable('sqlite storage is closed')
160	    if (this.options.role === 'read') {
161	      const idle = this.#readers.pop()
162	      if (idle !== undefined) return idle
163	      if (this.#openReaders < MAX_READERS) {
164	        const connection = new NodeSqliteConnection(this.#open('read'), 'read', this.#resolver)
165	        this.#openReaders += 1
166	        return connection
167	      }
168	      // 到上限：排队等一个读句柄被释放
169	      return new Promise<DatabaseConnection>(resolve => this.#readerWaiters.push(resolve))
170	    }
171	    if (this.#writer === undefined) throw new StorageUnavailable('sqlite storage is closed')
172	    // 写：进程内队列，同一实例的多个 write 顺序共用一个句柄
173	    const previous = this.#writeQueue
174	    let release!: () => void
175	    this.#writeQueue = new Promise<void>(resolve => {
176	      release = resolve
177	    })
178	    await previous
179	    if (this.#closed || this.#writer === undefined) {
180	      release()
181	      throw new StorageUnavailable('sqlite storage is closed')
182	    }
183	    this.#writerRelease = release
184	    return this.#writer
185	  }
186	  #writerRelease: (() => void) | undefined
187	
188	  async beginTransaction(
189	    connection: DatabaseConnection,
190	    settings: TransactionSettings,
191	  ): Promise<void> {
192	    const c = connection as NodeSqliteConnection
193	    if (c.role === 'read') {
194	      c.db.exec('BEGIN')
195	      return
196	    }
197	    if (settings.accessMode === 'read only')
198	      throw new Error('read transaction requested on the write handle (provider bug)')
199	    const deadline = Date.now() + (this.options.writeLockTimeoutMs ?? WRITE_LOCK_TIMEOUT_MS)
200	    let attempt = 0
201	    for (;;) {
202	      try {
203	        c.db.exec('BEGIN IMMEDIATE')
204	        return
205	      } catch (error) {
206	        if (!isSqliteBusy(error) || Date.now() >= deadline) {
207	          throw translateSqliteError(error, 'other', () => undefined)
208	        }
209	        await sleep(RETRY_BACKOFF_MS[Math.min(attempt, RETRY_BACKOFF_MS.length - 1)]!)
210	        attempt += 1
211	      }
212	    }
213	  }
214	
215	  async commitTransaction(connection: DatabaseConnection): Promise<void> {
216	    const c = connection as NodeSqliteConnection
217	    try {
218	      c.db.exec('COMMIT')
219	    } catch (error) {
220	      throw translateSqliteError(error, 'other', () => undefined)
221	    }
222	  }
223	
224	  async rollbackTransaction(connection: DatabaseConnection): Promise<void> {
225	    const c = connection as NodeSqliteConnection
226	    try {
227	      if (c.db.isTransaction) c.db.exec('ROLLBACK')
228	    } catch (error) {
229	      throw translateSqliteError(error, 'other', () => undefined)
230	    }
231	  }
232	
233	  async releaseConnection(connection: DatabaseConnection): Promise<void> {
234	    const c = connection as NodeSqliteConnection
235	    if (c.role === 'write') {
236	      const release = this.#writerRelease
237	      this.#writerRelease = undefined
238	      release?.()
239	      return
240	    }
241	    if (this.#closed) {
242	      c.db.close()
243	      return
244	    }
245	    const waiter = this.#readerWaiters.shift()
246	    if (waiter !== undefined) {
247	      waiter(c)
248	      return
249	    }
250	    this.#readers.push(c)
251	  }
252	
253	  /** 关准入 → 等在途写排空 → 关全部句柄。 */
254	  async destroy(): Promise<void> {
255	    this.#closed = true
256	    await this.#writeQueue
257	    const failures: unknown[] = []
258	    for (const db of this.#native) {
259	      try {
260	        if (db.isOpen) db.close()
261	      } catch (error) {
262	        failures.push(error)
263	      }
264	      if (db.isOpen) retainedNativeHandles.add(db)
265	      else {
266	        retainedNativeHandles.delete(db)
267	        this.#native.delete(db)
268	      }
269	    }
270	    if (failures.length > 0) throw new AggregateError(failures, 'sqlite handles failed to close')
271	    this.#writer = undefined
272	    this.#readers = []
273	  }
274	}
275	
276	export class NodeSqliteDialect implements Dialect {
277	  readonly driver: NodeSqliteDriver
278	  constructor(options: NodeSqliteDialectOptions) {
279	    this.driver = new NodeSqliteDriver(options)
280	  }
281	  createDriver(): Driver {
282	    return this.driver
283	  }
284	  createQueryCompiler() {
285	    return new SqliteQueryCompiler()
286	  }
287	  createAdapter() {
288	    return new SqliteAdapter()
289	  }
290	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
291	  createIntrospector(db: Kysely<any>) {
292	    return new SqliteIntrospector(db)
293	  }
294	}
