1	import { constants } from 'node:fs'
2	import { lstat, mkdir, open, realpath } from 'node:fs/promises'
3	import { basename, dirname, isAbsolute, join, resolve } from 'node:path'
4	import type { HostConfig } from './config.ts'
5	import { HostStartupFailure } from './failure.ts'
6	
7	function hasCode(error: unknown, code: string): boolean {
8	  return error instanceof Error && 'code' in error && error.code === code
9	}
10	async function syncDirectory(path: string): Promise<void> {
11	  const handle = await open(path, constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW)
12	  try {
13	    await handle.sync()
14	  } finally {
15	    await handle.close()
16	  }
17	}
18	
19	/** Run after key/config validation, before any storage plugin or plaintext workspace. */
20	export async function prepareBackupDirectory(config: HostConfig): Promise<string> {
21	  if (config.storage.dialect !== 'sqlite')
22	    throw new HostStartupFailure('config', 'bounded governance requires SQLite')
23	  try {
24	    const file = resolve(config.storage.file)
25	    const source = join(await realpath(dirname(file)), basename(file))
26	    // Final-component symlinks must not turn the default into a second source identity.
27	    try {
28	      const info = await lstat(source)
29	      if (!info.isFile() || info.isSymbolicLink()) throw new Error('source is not a regular file')
30	    } catch (error) {
31	      if (!hasCode(error, 'ENOENT')) throw error
32	    }
33	    const requested = config.backupDirectory ?? `${source}.backups`
34	    if (!isAbsolute(requested)) throw new Error('backup directory is not absolute')
35	    const parent = await realpath(dirname(resolve(requested)))
36	    const path = join(parent, basename(resolve(requested)))
37	    if (path === parent) throw new Error('backup directory must have an existing parent')
38	    try {
39	      await mkdir(path, { mode: 0o700 })
40	    } catch (error) {
41	      if (!hasCode(error, 'EEXIST')) throw error
42	    }
43	    const info = await lstat(path)
44	    if (
45	      !info.isDirectory() ||
46	      info.isSymbolicLink() ||
47	      info.uid !== process.getuid?.() ||
48	      (info.mode & 0o077) !== 0
49	    )
50	      throw new Error('backup directory is not private')
51	    await syncDirectory(path)
52	    await syncDirectory(parent)
53	    return path
54	  } catch (error) {
55	    throw new HostStartupFailure('config', 'backup directory cannot be prepared durably', {
56	      item: 'OMNE_TENANCY_BACKUP_DIR',
57	      cause: error,
58	    })
59	  }
60	}
