1	// 进程形态（architecture「拓扑与进程模型」：建包时定）：服务、部署密钥和本机维护命令。
2	//   keygen <dir>  一次性生成两对部署密钥，写四份 0600 PEM；标准输出给出四个 `_FILE` 变量与路径（不含密钥内容）。
3	//   serve         从环境变量起治理中心；SIGTERM／SIGINT ⇒ 逆序撤除 ⇒ 撤完退出 0，30秒仅诊断继续等；收场未确认或启动失败 ⇒ 退出 1。
4	// 启动失败与撤除的结构化记录由 boot() 写进标准错误流（JSONL）；本模块只决定退出码。
5	
6	export const EXIT = { ok: 0, failed: 1, usage: 64 } as const
7	
8	export interface MainIo {
9	  readonly stdout: (line: string) => void | Promise<void>
10	  readonly stderr: (line: string) => void | Promise<void>
11	  /** 等到一个停机信号。 */
12	  readonly shutdownSignal: () => Promise<string>
13	  readonly releaseShutdownSignal?: () => void
14	}
15	
16	function createProcessIo(): MainIo {
17	  let release = () => {}
18	  return {
19	    stdout: line =>
20	      new Promise<void>((resolve, reject) =>
21	        process.stdout.write(line, error => (error ? reject(error) : resolve())),
22	      ),
23	    stderr: line =>
24	      new Promise<void>((resolve, reject) =>
25	        process.stderr.write(line, error => (error ? reject(error) : resolve())),
26	      ),
27	    shutdownSignal: () =>
28	      new Promise(resolve => {
29	        const stop = (signal: string) => {
30	          release()
31	          resolve(signal)
32	        }
33	        release = () => {
34	          process.off('SIGTERM', stop)
35	          process.off('SIGINT', stop)
36	        }
37	        process.on('SIGTERM', stop)
38	        process.on('SIGINT', stop)
39	      }),
40	    releaseShutdownSignal: () => release(),
41	  }
42	}
43	
44	const USAGE =
45	  'usage: tenancy-host keygen <directory> | serve | ops --socket-dir <absolute> full-health|backup [--only-if-due]|backup-status | verify --source <absolute> --work-dir <absolute> | restore-isolated --source <absolute> --target <new-absolute-directory> --work-dir <absolute>\n'
46	
47	export async function main(
48	  argv: readonly string[],
49	  io: MainIo = createProcessIo(),
50	): Promise<number> {
51	  const [command, ...rest] = argv
52	  if (command === 'keygen') {
53	    const [directory] = rest
54	    if (directory === undefined || rest.length !== 1) {
55	      await io.stderr(USAGE)
56	      return EXIT.usage
57	    }
58	    try {
59	      const { generateKeyFiles } = await import('./keys.ts')
60	      const files = await generateKeyFiles(directory)
61	      await io.stdout(`${JSON.stringify({ event: 'keys-generated', files })}\n`)
62	      return EXIT.ok
63	    } catch (error) {
64	      const name = error instanceof Error ? error.name : typeof error
65	      const message = error instanceof Error ? error.message : 'non-error value thrown'
66	      await io.stderr(`${JSON.stringify({ event: 'keygen-failed', errorType: name, message })}\n`)
67	      return EXIT.failed
68	    }
69	  }
70	  if (command === 'serve' && rest.length === 0) {
71	    const signal = io.shutdownSignal()
72	    try {
73	      const { boot } = await import('./boot.ts')
74	      const host = await boot()
75	      await signal
76	      const disposal = await host.dispose()
77	      return disposal.complete ? EXIT.ok : EXIT.failed
78	    } catch {
79	      return EXIT.failed
80	    } finally {
81	      io.releaseShutdownSignal?.()
82	    }
83	  }
84	  if (command === 'ops' || command === 'verify' || command === 'restore-isolated') {
85	    const { parseMaintenanceCommand, runMaintenanceCommand } =
86	      await import('./maintenance-command.ts')
87	    const parsed = parseMaintenanceCommand(argv)
88	    if (parsed === undefined) {
89	      await io.stderr(USAGE)
90	      return EXIT.usage
91	    }
92	    const abort = new AbortController()
93	    const signal = io.shutdownSignal()
94	    void signal.then(
95	      () => abort.abort(),
96	      () => abort.abort(),
97	    )
98	    try {
99	      return await runMaintenanceCommand(parsed, io, abort.signal)
100	    } finally {
101	      io.releaseShutdownSignal?.()
102	    }
103	  }
104	  await io.stderr(USAGE)
105	  return EXIT.usage
106	}
