2	// 撤除（一个 effect）：守卫置为已撤、关准入 → 等在途 → 关句柄 → 恢复未确认的快照 → 放排他。
3	import type { Context } from '@deepseek-ai/cordis'
4	import { definePlugin } from '@omne-harness-lite/kernel-basis'
5	import { StorageSqlConfig } from './config.ts'
6	import { openStorage } from './open.ts'
7	import type { SqlStorage } from './provider.ts'
8	
9	export const STORAGE_SERVICE = 'storage' as const
10	
11	function describe(error: unknown): string {
12	  return error instanceof Error ? error.message : String(error)
13	}
14	
15	/** 撤除收尾的失败内核不上抛（basis effect-disposal-concurrent-not-ordered）：在这里记 error，装配经 guard.pending() 回头看磁盘。 */
16	async function closeLogged(ctx: Context, storage: SqlStorage): Promise<void> {
17	  try {
18	    await storage.close()
19	  } catch (error) {
20	    ctx.logger.error('storage-sql: dispose failed: %s', describe(error))
21	  }
22	}
