24	export const storageSqlPlugin = definePlugin<StorageSqlConfig>({
25	  name: 'storage-sql',
26	  Config: StorageSqlConfig,
27	  async apply(ctx: Context, config) {
28	    const storage = await openStorage(config, { logger: ctx.logger })
29	    try {
30	      // 启动期（await 期间）fiber 已被 dispose 时 effect 抛 INACTIVE_EFFECT：资源没有归宿，自己收尾再抛
31	      ctx.effect(() => () => closeLogged(ctx, storage))
