1	// P-13：显式事务参与。ALS 只跟踪单元内调用帧，不合并普通 Storage 调用。
2	import { AsyncLocalStorage } from 'node:async_hooks'
3	import {
4	  ReferenceViolation,
5	  StorageDefect,
6	  UniqueViolation,
7	  type ReadTx,
8	  type Storage,
9	  type StorageUnit,
10	  type WriteTx,
11	} from '@omne-harness-lite/storage'
12	
13	interface Frame {
14	  readonly parent?: Frame
15	  active: boolean
16	  busy: boolean
17	}
18	
19	export class SqlStorageUnit implements StorageUnit {
20	  readonly #frames = new AsyncLocalStorage<Frame>()
21	  readonly #jobs = new Set<Promise<unknown>>()
22	  readonly #notifications: (() => void)[] = []
23	  #closed = false
24	  // 单独记录存在性：JavaScript 可以 throw undefined / null / false。
25	  #failure: { readonly error: unknown } | undefined
26	
27	  constructor(
28	    private readonly storage: Storage,
29	    private readonly tx: WriteTx,
30	  ) {}
31	
32	  #fail(message: string): never {
33	    const error = new StorageDefect(message)
34	    this.#failure ??= { error }
35	    throw error
36	  }
37	
38	  #frame(): Frame {
39	    if (this.#closed) this.#fail('storage unit is closed')
40	    if (this.#failure !== undefined) throw this.#failure.error
41	    const frame = this.#frames.getStore()
42	    if (frame === undefined) this.#fail('storage unit used outside its callback')
43	    for (let at: Frame | undefined = frame; at !== undefined; at = at.parent) {
44	      if (!at.active) this.#fail('storage unit call frame has ended')
45	    }
46	    return frame
47	  }
48	
49	  assertStorage(expected: Storage): void {
50	    if (this.#frame().busy) this.#fail('storage unit calls overlap')
51	    if (expected !== this.storage) this.#fail('storage unit belongs to a different instance')
52	  }
53	
54	  #invoke<T>(fn: () => Promise<T>, statement: boolean): Promise<T> {
55	    const parent = this.#frame()
56	    if (parent.busy) this.#fail('storage unit calls overlap')
57	    parent.busy = true
58	    const frame: Frame = { parent, active: true, busy: false }
59	    const job = Promise.resolve()
60	      .then(() =>
61	        this.#frames.run(frame, () => {
62	          this.#frame()
63	          return fn()
64	        }),
65	      )
66	      .catch((error: unknown) => {
67	        // P-2 只在语句回调出口保留可恢复性；逃出 run 的任何异常都污染。
68	        if (
69	          !statement ||
70	          !(error instanceof UniqueViolation || error instanceof ReferenceViolation)
71	        ) {
72	          this.#failure ??= { error }
73	        }
74	        throw error
75	      })
76	      .finally(() => {
77	        frame.active = false
78	        parent.busy = false
79	        this.#jobs.delete(job)
80	      })
81	    this.#jobs.add(job)
82	    // 接纳时就观察拒绝；不改变交给调用方的原 Promise。
83	    void job.catch(() => undefined)
84	    return job
85	  }
86	
87	  run<T>(fn: () => Promise<T>): Promise<T> {
88	    return this.#invoke(fn, false)
89	  }
90	
91	  query<T>(fn: (tx: ReadTx) => Promise<T>): Promise<T> {
92	    return this.#invoke(() => fn({ db: this.tx.db }), true)
93	  }
94	
95	  mutate<T>(fn: (tx: WriteTx) => Promise<T>): Promise<T> {
96	    return this.#invoke(() => fn(this.tx), true)
97	  }
98	
99	  afterCommit(notify: () => void): void {
100	    if (this.#frame().busy) this.#fail('storage unit calls overlap')
101	    this.#notifications.push(notify)
102	  }
103	
104	  async execute<T>(fn: (unit: StorageUnit) => Promise<T>): Promise<T> {
105	    const root: Frame = { active: true, busy: false }
106	    let result: { readonly value: T } | undefined
107	    try {
108	      result = { value: await this.#frames.run(root, () => fn(this)) }
109	    } catch (error) {
110	      this.#failure ??= { error }
111	    } finally {
112	      root.active = false
113	      this.#closed = true
114	    }
115	    if (this.#jobs.size > 0) {
116	      this.#failure ??= {
117	        error: new StorageDefect('storage unit callback ended with calls still in flight'),
118	      }
119	    }
120	    // 关闭新准入后已接纳的 SQL 仍需收场；不能先回滚/关连接。
121	    await Promise.allSettled([...this.#jobs])
122	    if (this.#failure !== undefined) throw this.#failure.error
123	    if (result === undefined) throw new StorageDefect('storage unit completed without a result')
124	    return result.value
125	  }
126	
127	  /** 仅实际提交拥有者调用；已退出写事务和本单元 ALS。 */
128	  publish(reportFailure: () => void): void {
129	    const report = () => {
130	      try {
131	        reportFailure()
132	      } catch {
133	        // 诊断提供者失败不能改写已提交的业务结果；不输出原异常/秘密。
134	        console.error('storage-sql: after-commit notification diagnostic failed')
135	      }
136	    }
137	    for (const notify of this.#notifications.splice(0)) {
138	      try {
139	        const result: unknown = notify()
140	        if (result !== undefined) {
141	          report()
142	          // 非 void 返回是误用；仍立即观察可能的 Promise 拒绝，不等待它。
143	          void Promise.resolve(result).catch(report)
144	        }
145	      } catch {
146	        report()
147	      }
148	    }
149	  }
150	}
