1	// 运维面的本机套接字（https-json/1 S-20；入口契约 S-25）：部署配置给的目录下恰为 `governance-center-ops.sock`。
2	// 「只在本机可达」由操作系统的文件访问控制兑现：目录只对中心的运行用户可访问，否则启动失败，中心不替运维者改权限。
3	// 启动失败说明不含 config 的值（目录路径也不写）。
4	import { lstat, stat, unlink } from 'node:fs/promises'
5	import { type Server, connect, createServer } from 'node:net'
6	import { join } from 'node:path'
7	
8	export const OPS_SOCKET_NAME = 'governance-center-ops.sock'
9	
10	export type OpsSocketFailure =
11	  | 'directory-missing'
12	  | 'not-a-directory'
13	  | 'directory-permissions'
14	  | 'unsupported-platform'
15	  | 'socket-in-use'
16	  | 'not-a-socket'
17	  | 'unusable'
18	
19	const EXPLANATIONS: Record<OpsSocketFailure, string> = {
20	  'directory-missing': 'the ops socket directory does not exist',
21	  'not-a-directory': 'the ops socket directory is not a directory',
22	  'directory-permissions':
23	    'the ops socket directory must be owned by the running user and grant no permission to group or others',
24	  'unsupported-platform': 'the ops face needs POSIX file ownership (process.getuid)',
25	  'socket-in-use': `another process is listening on ${OPS_SOCKET_NAME}; another center instance may be running`,
26	  'not-a-socket': `${OPS_SOCKET_NAME} exists and is not a socket; refusing to remove it`,
27	  unusable: `${OPS_SOCKET_NAME} could not be prepared or bound`,
28	}
29	
30	export class OpsSocketError extends Error {
31	  override readonly name = 'OpsSocketError'
32	  readonly failure: OpsSocketFailure
33	
34	  constructor(failure: OpsSocketFailure, options?: { readonly cause?: unknown }) {
35	    super(`governance-center-ops: ${EXPLANATIONS[failure]}`, options)
36	    this.failure = failure
37	  }
38	}
39	
40	function errorCode(error: unknown): string | undefined {
41	  return error instanceof Error && 'code' in error && typeof error.code === 'string'
42	    ? error.code
43	    : undefined
44	}
45	
46	/** 目录核验：存在、是目录、所有者是运行用户、组与其他用户没有任何权限位。 */
47	async function verifyDirectory(directory: string): Promise<void> {
48	  let info
49	  try {
50	    info = await stat(directory)
51	  } catch (error) {
52	    throw new OpsSocketError(errorCode(error) === 'ENOENT' ? 'directory-missing' : 'unusable', {
53	      cause: error,
54	    })
55	  }
56	  if (!info.isDirectory()) throw new OpsSocketError('not-a-directory')
57	  const uid = process.getuid?.()
58	  if (uid === undefined) throw new OpsSocketError('unsupported-platform')
59	  if (info.uid !== uid || (info.mode & 0o077) !== 0)
60	    throw new OpsSocketError('directory-permissions')
61	}
62	
63	/** 试连一个已有的套接字文件：连得上 ⇒ 有人在听。 */
64	function someoneListens(path: string): Promise<boolean> {
65	  return new Promise((resolve, reject) => {
66	    const probe = connect(path)
67	    probe.once('connect', () => {
68	      probe.destroy()
69	      resolve(true)
70	    })
71	    probe.once('error', error => {
72	      probe.destroy()
73	      if (errorCode(error) === 'ECONNREFUSED') resolve(false)
74	      else reject(error)
75	    })
76	  })
77	}
78	
79	/**
80	 * 核目录、处理那个位置上已有的文件：有人在听的套接字 ⇒ 启动失败、不抢占；没人在听的 ⇒ 上次的残留，删掉；
81	 * 不是套接字 ⇒ 启动失败、不删。返回套接字路径。
82	 */
83	export async function prepareSocketPath(directory: string): Promise<string> {
84	  await verifyDirectory(directory)
85	  const path = join(directory, OPS_SOCKET_NAME)
86	  let existing
87	  try {
88	    existing = await lstat(path)
89	  } catch (error) {
90	    if (errorCode(error) === 'ENOENT') return path
91	    throw new OpsSocketError('unusable', { cause: error })
92	  }
93	  if (!existing.isSocket()) throw new OpsSocketError('not-a-socket')
94	  let listening: boolean
95	  try {
96	    listening = await someoneListens(path)
97	  } catch (error) {
98	    throw new OpsSocketError('unusable', { cause: error })
99	  }
100	  if (listening) throw new OpsSocketError('socket-in-use')
101	  try {
102	    await unlink(path)
103	  } catch (error) {
104	    if (errorCode(error) !== 'ENOENT') throw new OpsSocketError('unusable', { cause: error })
105	  }
106	  return path
107	}
108	
109	/** 在套接字路径上监听（`allowHalfOpen`：对端先半关也要写得出答复）。 */
110	export function listenOnSocket(path: string): Promise<Server> {
111	  const server = createServer({ allowHalfOpen: true })
112	  return new Promise((resolve, reject) => {
113	    const onError = (error: Error) => {
114	      server.off('listening', onListening)
115	      reject(
116	        new OpsSocketError(errorCode(error) === 'EADDRINUSE' ? 'socket-in-use' : 'unusable', {
117	          cause: error,
118	        }),
119	      )
120	    }
121	    const onListening = () => {
122	      server.off('error', onError)
123	      resolve(server)
124	    }
125	    server.once('error', onError)
126	    server.once('listening', onListening)
127	    server.listen(path)
128	  })
129	}
130	
131	/** 撤除收尾：删掉本实例绑定的套接字文件（已不在不算错）。 */
132	export async function removeSocketFile(path: string): Promise<void> {
133	  try {
134	    await unlink(path)
135	  } catch (error) {
136	    if (errorCode(error) !== 'ENOENT') throw error
137	  }
138	}
