1	import { StorageUnavailable } from '@omne-harness-lite/storage'
2	// 判定次序第 ② 步：认人（入口契约 S-11；入口节点约束第 8 条「只凭出示物认人」）。
3	// **`Caller` 只在本模块构造**：路由调用函数以登录状态为发起方或调用方时，实参只从它取；
4	// 它的两个值只来自 `logins.exchange` 的返回——线上收到的任何 `LoginStateId` 都不作认人依据。
5	import {
6	  type ExchangedIdentity,
7	  type LoginsService,
8	  parseLoginStatePresentation,
9	} from '@omne-harness-lite/account-identity'
10	import {
11	  type AccountId,
12	  type LoginStateId,
13	  isOk,
14	  validate,
15	} from '@omne-harness-lite/identity-values'
16	import { type Observed, type Rejection, thrownValue } from './record.ts'
17	
18	/** 认人所得（S-12）。私有字段让它名义上唯一：本模块之外构造不出来（类本身不导出）。 */
19	class CallerIdentity {
20	  readonly #nominal = true
21	  readonly loginStateId: LoginStateId
22	  readonly accountId: AccountId
23	
24	  constructor(identity: ExchangedIdentity) {
25	    this.loginStateId = identity.loginStateId
26	    this.accountId = identity.accountId
27	  }
28	}
29	
30	export type Caller = CallerIdentity
31	
32	export type Authentication =
33	  | { readonly kind: 'caller'; readonly caller: Caller }
34	  /** 六种不认情形同一个线上答复；记录里可以区分到 `rejection` 这一步。 */
35	  | { readonly kind: 'rejected'; readonly rejection: Rejection }
36	  | { readonly kind: 'unavailable'; readonly observed: Observed }
37	  | { readonly kind: 'defect'; readonly observed: Observed }
38	
39	/**
40	 * 出示物的三种不查即判（没带、带了不止一个、表示层不合格 ⇒ 不调 `exchange`），其余现读 AI S-44。
41	 * `occurrences` 是信封顶层 `presentedLoginState` 出现的次数（重复由读取器报出）。
42	 */
43	export async function authenticate(
44	  presented: unknown,
45	  occurrences: number,
46	  logins: Pick<LoginsService, 'exchange'>,
47	): Promise<Authentication> {
48	  if (occurrences === 0) return { kind: 'rejected', rejection: 'absent' }
49	  if (occurrences > 1) return { kind: 'rejected', rejection: 'multiple' }
50	  // 表示层就是 AI S-45 的交换表示，用账号能力包导出的同一个函数判（S-5），不另立一条
51	  const presentation = parseLoginStatePresentation(presented)
52	  if (!isOk(presentation)) return { kind: 'rejected', rejection: 'malformed' }
53	  let outcome: Awaited<ReturnType<LoginsService['exchange']>>
54	  try {
55	    outcome = await logins.exchange(presentation.ok)
56	  } catch (error) {
57	    if (error instanceof StorageUnavailable) throw error
58	    return defect(thrownValue(error))
59	  }
60	  // 参与方的返回按运行期形状核：失败集合之外的任何东西（含没有值）都是缺陷
61	  const shape: unknown = outcome
62	  if (typeof shape !== 'object' || shape === null) return defect('not-an-outcome')
63	  if ('ok' in outcome) {
64	    const identity: unknown = outcome.ok
65	    if (
66	      typeof identity !== 'object' ||
67	      identity === null ||
68	      !('loginStateId' in identity) ||
69	      !('accountId' in identity) ||
70	      !validate('LoginStateId', identity.loginStateId).valid ||
71	      !validate('AccountId', identity.accountId).valid
72	    ) {
73	      return defect('malformed-identity')
74	    }
75	    return { kind: 'caller', caller: new CallerIdentity(outcome.ok) }
76	  }
77	  switch (outcome.failure) {
78	    // 查不到、已撤销、所属账号未激活，以及本版到不了的表示层不合格：都是「不认」（S-11 出口表）
79	    case 'login-state-rejected':
80	    case 'invalid-input':
81	      return { kind: 'rejected', rejection: 'judged' }
82	    case 'storage-unavailable':
83	      return { kind: 'unavailable', observed: { call: 'authenticate', value: outcome.failure } }
84	    default:
85	      return defect('outside-failure-set')
86	  }
87	}
88	
89	function defect(value: string): Authentication {
90	  return { kind: 'defect', observed: { call: 'authenticate', value } }
91	}
