1	import { createRequire } from 'node:module'
2	import { Ajv2020 } from 'ajv/dist/2020.js'
3	import { GovernanceClientConfigurationError, type PublicHealthOptions } from './config.ts'
4	import type { EntryAnswer, HealthUnavailableReason } from './protocol.ts'
5	import { sendRequest } from './transport.ts'
6	
7	export type GovernanceOutcome = (
8	  | {
9	      readonly kind: 'reply'
10	      readonly reply: { readonly result: unknown } | { readonly failure: string }
11	    }
12	  | { readonly kind: 'entry-answer'; readonly answer: EntryAnswer }
13	  | { readonly kind: 'unavailable'; readonly reason: HealthUnavailableReason }
14	) & { readonly sendAttempted: boolean }
15	
16	const require = createRequire(import.meta.url)
17	const schema: { readonly $id: string } = require('../schema/governance-center-entry.schema.json')
18	const ajv = new Ajv2020({
19	  strict: true,
20	  strictTypes: false,
21	  strictRequired: false,
22	  validateFormats: false,
23	})
24	ajv.addKeyword('x-counterexamples')
25	ajv.addSchema(require('@omne-harness-lite/identity-values/schema'))
26	ajv.addSchema(require('@omne-harness-lite/offer-expiry/schema'))
27	ajv.addSchema(schema)
28	const envelopeSchema = ajv.compile({ $ref: `${schema.$id}#/$defs/Envelope` })
29	const exchangeSchema = ajv.compile({ $ref: `${schema.$id}#/$defs/Exchange` })
30	const VERSION_MISMATCH = Buffer.from('"version-mismatch"')
31	
32	function record(value: unknown): value is Record<string, unknown> {
33	  return typeof value === 'object' && value !== null && !Array.isArray(value)
34	}
35	
36	type Reading =
37	  { readonly kind: 'value'; readonly value: unknown } | { readonly kind: 'invalid' | 'limit' }
38	
39	/** Native JSON syntax parsing plus bounded token inspection for duplicate keys.
40	 * The token walk does not interpret values or implement a second JSON grammar.
41	 */
42	function readReplyJson(body: Buffer): Reading {
43	  let text: string
44	  let value: unknown
45	  try {
46	    text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body)
47	    value = JSON.parse(text)
48	  } catch {
49	    return { kind: 'invalid' }
50	  }
51	  const stack: ({ readonly keys: Set<string>; expectingKey: boolean } | undefined)[] = []
52	  for (const match of text.matchAll(/"(?:[^"\\]|\\[\s\S])*"|[{}\[\],:]/g)) {
53	    const token = match[0]
54	    if (token === '{' || token === '[') {
55	      if (stack.length === 64) return { kind: 'limit' }
56	      stack.push(token === '{' ? { keys: new Set(), expectingKey: true } : undefined)
57	    } else if (token === '}' || token === ']') stack.pop()
58	    else {
59	      const frame = stack.at(-1)
60	      if (frame === undefined) continue
61	      if (token === ',') frame.expectingKey = true
62	      else if (token.startsWith('"') && frame.expectingKey) {
63	        const key: string = JSON.parse(token)
64	        if (frame.keys.has(key)) return { kind: 'invalid' }
65	        if (frame.keys.size === 1024) return { kind: 'limit' }
66	        frame.keys.add(key)
67	        frame.expectingKey = false
68	      }
69	    }
70	  }
71	  return { kind: 'value', value }
72	}
73	
74	/** D045: validates one EC2 exchange. Callers own center binding, secrets,
75	 * local persistence and presentation; this function never retries or logs.
76	 */
77	export async function exchangeGovernance(
78	  options: PublicHealthOptions,
79	  input: unknown,
80	): Promise<GovernanceOutcome> {
81	  let body: Buffer
82	  let envelope: unknown
83	  try {
84	    const encoded = JSON.stringify(input)
85	    if (encoded === undefined) throw new TypeError('missing envelope')
86	    body = Buffer.from(encoded)
87	    envelope = JSON.parse(encoded)
88	  } catch {
89	    throw new GovernanceClientConfigurationError('governance envelope cannot be encoded')
90	  }
91	  if (!record(envelope) || envelope['protocolVersion'] !== '2' || !envelopeSchema(envelope)) {
92	    throw new GovernanceClientConfigurationError('governance envelope does not conform to EC2')
93	  }
94	  const operation = envelope['operation']
95	  const payload = envelope['payload']
96	  const response = await sendRequest(options, body)
97	  if (response.kind === 'unavailable') return response
98	  const { sendAttempted } = response
99	  if (response.body.equals(VERSION_MISMATCH))
100	    return { kind: 'entry-answer', answer: 'version-mismatch', sendAttempted }
101	  if (response.status !== 200)
102	    return { kind: 'unavailable', reason: 'response-invalid', sendAttempted }
103	  const read = readReplyJson(response.body)
104	  if (read.kind !== 'value')
105	    return {
106	      kind: 'unavailable',
107	      reason: read.kind === 'limit' ? 'response-limit' : 'response-invalid',
108	      sendAttempted,
109	    }
110	  const reply = read.value
111	  if (!exchangeSchema({ operation, reply }))
112	    return { kind: 'unavailable', reason: 'response-invalid', sendAttempted }
113	  if (reply === 'login-state-rejected' || reply === 'invalid-input' || reply === 'unavailable')
114	    return { kind: 'entry-answer', answer: reply, sendAttempted }
115	  if (!record(reply)) return { kind: 'unavailable', reason: 'response-invalid', sendAttempted }
116	  if ('result' in reply) {
117	    // EC2 OG34 has two request-dependent branches sharing one route identifier.
118	    if (
119	      operation === 'capability.organization-governance/v2#S-34' &&
120	      record(payload) &&
121	      Array.isArray(payload['organizations'])
122	    ) {
123	      const one = payload['organizations'].length === 1
124	      if (one ? !Array.isArray(reply['result']) : typeof reply['result'] !== 'boolean')
125	        return { kind: 'unavailable', reason: 'response-invalid', sendAttempted }
126	    }
127	    return { kind: 'reply', reply: { result: reply['result'] }, sendAttempted }
128	  }
129	  if (typeof reply['failure'] === 'string')
130	    return { kind: 'reply', reply: { failure: reply['failure'] }, sendAttempted }
131	  return { kind: 'unavailable', reason: 'response-invalid', sendAttempted }
132	}
