1	export type CenterTrust =
2	  | { readonly mode: 'ca'; readonly certificateAuthorities?: string | Uint8Array }
3	  | { readonly mode: 'spki'; readonly sha256: string }
4	
5	export interface PublicHealthOptions {
6	  readonly url: string | URL
7	  /** SPKI必须已由调用方确认；本包没有发现/接受/保存信任的副作用。 */
8	  readonly trust?: CenterTrust
9	  readonly timeoutMs?: number
10	  readonly signal?: AbortSignal
11	}
12	
13	export class GovernanceClientConfigurationError extends Error {
14	  override readonly name = 'GovernanceClientConfigurationError'
15	}
16	
17	export interface HealthRequestConfiguration {
18	  readonly url: URL
19	  readonly ca: Buffer | undefined
20	  readonly pin: string | undefined
21	  readonly timeoutMs: number
22	  readonly signal: AbortSignal | undefined
23	}
24	
25	export function captureConfiguration(options: PublicHealthOptions): HealthRequestConfiguration {
26	  let url: URL
27	  try {
28	    url = new URL(options.url)
29	  } catch {
30	    throw new GovernanceClientConfigurationError('center URL must be a valid HTTPS URL')
31	  }
32	  if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash)
33	    throw new GovernanceClientConfigurationError(
34	      'center URL requires HTTPS without userinfo, query or fragment',
35	    )
36	  const timeoutMs = options.timeoutMs ?? 10_000
37	  if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 120_000)
38	    throw new GovernanceClientConfigurationError('timeoutMs must be an integer from 1 to 120000')
39	  const trust = options.trust ?? { mode: 'ca' }
40	  let ca: Buffer | undefined
41	  let pin: string | undefined
42	  switch (trust.mode) {
43	    case 'ca': {
44	      if (trust.certificateAuthorities !== undefined) {
45	        ca = Buffer.from(trust.certificateAuthorities)
46	        if (ca.length === 0)
47	          throw new GovernanceClientConfigurationError('certificateAuthorities cannot be empty')
48	      }
49	      break
50	    }
51	    case 'spki': {
52	      if (!/^[0-9a-fA-F]{64}$/.test(trust.sha256))
53	        throw new GovernanceClientConfigurationError(
54	          'SPKI SHA256 must contain 64 hexadecimal digits',
55	        )
56	      pin = trust.sha256.toLowerCase()
57	      break
58	    }
59	    default:
60	      throw new GovernanceClientConfigurationError('unsupported center trust mode')
61	  }
62	  return { url, ca, pin, timeoutMs, signal: options.signal }
63	}
