1	import { constants } from 'node:fs'
2	import { mkdir, open, type FileHandle } from 'node:fs/promises'
3	import { dirname, isAbsolute, join, parse, resolve } from 'node:path'
4	import { ClientStateOpenFailure } from './surface.ts'
5	
6	export function ioCode(error: unknown): string | undefined {
7	  return error instanceof Error && 'code' in error && typeof error.code === 'string'
8	    ? error.code
9	    : undefined
10	}
11	export function unavailableIo(error: unknown): boolean {
12	  return [
13	    'EIO',
14	    'ENOSPC',
15	    'EDQUOT',
16	    'EMFILE',
17	    'ENFILE',
18	    'EACCES',
19	    'EPERM',
20	    'EROFS',
21	    'ENOENT',
22	    'EBUSY',
23	    'EINTR',
24	  ].includes(ioCode(error) ?? '')
25	}
26	
27	async function checkedDirectory(path: string, privateRoot: boolean): Promise<FileHandle> {
28	  const fd = await open(path, constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW)
29	  try {
30	    const stat = await fd.stat()
31	    const uid = process.getuid?.()
32	    const privateOk = stat.uid === uid && (stat.mode & 0o777) === 0o700
33	    // A root-owned sticky temporary directory prevents another UID replacing our child.
34	    const ancestorOk =
35	      (stat.uid === uid || stat.uid === 0) &&
36	      ((stat.mode & 0o022) === 0 || (stat.uid === 0 && (stat.mode & 0o1000) !== 0))
37	    if (!stat.isDirectory() || uid === undefined || !(privateRoot ? privateOk : ancestorOk))
38	      throw new ClientStateOpenFailure('unsafe-path')
39	    return fd
40	  } catch (error) {
41	    await fd.close()
42	    throw error
43	  }
44	}
45	
46	async function checkFile(file: string): Promise<void> {
47	  const fd = await open(file, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK)
48	  try {
49	    const stat = await fd.stat()
50	    if (!stat.isFile() || stat.uid !== process.getuid?.() || (stat.mode & 0o777) !== 0o600)
51	      throw new ClientStateOpenFailure('unsafe-path')
52	  } finally {
53	    await fd.close()
54	  }
55	}
56	
57	export async function checkSideFiles(file: string): Promise<void> {
58	  await checkFile(file)
59	  for (const suffix of ['-wal', '-shm']) {
60	    try {
61	      await checkFile(file + suffix)
62	    } catch (error) {
63	      if (ioCode(error) !== 'ENOENT') throw error
64	    }
65	  }
66	}
67	
68	export interface PrivateFiles {
69	  readonly file: string
70	  readonly creator: boolean
71	  sync(): Promise<void>
72	  close(): Promise<void>
73	}
74	
75	export async function prepareFiles(directory: string): Promise<PrivateFiles> {
76	  if (!isAbsolute(directory) || resolve(directory) !== directory)
77	    throw new ClientStateOpenFailure('invalid-directory')
78	  let root: FileHandle | undefined
79	  try {
80	    const parent = dirname(directory)
81	    const volume = parse(parent).root
