2	import type {
3	  ClientLocalState,
4	  LocalRecord,
5	  LocalSnapshot,
6	} from '@omne-harness-lite/client-local-state'
7	import { defect, origin, type ReportFrame } from './report.ts'
8	
9	export async function settle(
10	  state: ClientLocalState,
11	  before: LocalSnapshot,
12	  value: LocalRecord,
13	  frame: ReportFrame,
14	): Promise<LocalSnapshot | undefined> {
15	  const operationId = randomUUID()
16	  let outcome
17	  try {
18	    outcome = await state.compareAndReplace(before.token, value, operationId)
19	  } catch {
20	    frame.local = { status: 'defect' }
21	    defect(frame, 'settlement')
22	    return undefined
23	  }
24	  if (outcome.kind === 'installed') {
25	    frame.local = { status: 'installed' }
26	    return outcome.snapshot
27	  }
28	  if (outcome.kind === 'conflict') {
29	    frame.local = { status: 'conflict' }
30	    return outcome.current
31	  }
32	  if (outcome.kind === 'not-installed') {
33	    frame.local = { status: 'not-installed', reason: outcome.reason }
34	    return undefined
35	  }
36	  frame.local = { status: 'unconfirmed', recovery: { observation: 'unknown' } }
37	  try {
38	    const observed = await state.read()
39	    if (observed.kind !== 'read') return undefined
40	    const current = observed.snapshot
41	    const observation =
42	      current.storeId !== before.storeId
43	        ? 'different-store'
44	        : current.operationId === operationId
45	          ? 'visible-this-operation'
46	          : current.revision === before.revision
47	            ? 'not-seen'
48	            : 'visible-other-record'
49	    frame.local = {
50	      status: 'unconfirmed',
51	      recovery: { observation, current: { ...origin(current.value), revision: current.revision } },
52	    }
53	    return current
54	  } catch {
55	    defect(frame, 'recovery')
56	    return undefined
57	  }
58	}
