12	/** Validate before any public callback; a trust configuration is not display-safe by itself. */
13	function previewIntent(intent: ActionIntent): PreviewIntent {
14	  if (intent.action !== 'configure') return intent
15	  const url = new URL(intent.endpoint)
16	  if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash)
17	    throw new Error('invalid configuration')
18	  const trust = intent.trust
19	  if (trust.mode === 'spki') return { ...intent, endpoint: url.href, trust }
20	  const pem = trust.certificateAuthorities
21	  if (pem === undefined)
22	    return { ...intent, endpoint: url.href, trust: { mode: 'ca', source: 'system' } }
23	  const blocks = pem.match(/-----BEGIN CERTIFICATE-----[\s\S]*?-----END CERTIFICATE-----/g)
24	  if (
25	    blocks === null ||
26	    pem.replace(/-----BEGIN CERTIFICATE-----[\s\S]*?-----END CERTIFICATE-----/g, '').trim() !== ''
27	  )
28	    throw new Error('invalid CA material')
29	  for (const certificate of blocks)
30	    if (!new X509Certificate(certificate).ca) throw new Error('not a CA')
31	  return {
32	    ...intent,
33	    endpoint: url.href,
34	    trust: {
35	      mode: 'ca',
36	      source: 'explicit',
37	      sha256: createHash('sha256').update(pem, 'utf8').digest('hex'),
38	    },
39	  }
40	}
41	
42	/** One actual callback lifetime; abort requests completion but never substitutes for it. */
43	export class Prepared {
44	  readonly intent: ActionIntent
45	  readonly #preview: PreviewIntent
46	  readonly #controller = new AbortController()
47	  #prompt: InputPrompt | undefined
48	  private constructor(intent: ActionIntent, preview: PreviewIntent, prompt: InputPrompt) {
49	    this.intent = intent
50	    this.#preview = preview
51	    this.#prompt = prompt
52	  }
53	  static capture(input: unknown, prompt: InputPrompt): Prepared | undefined {
54	    const intent = captureIntent(input)
55	    if (intent === undefined || typeof prompt !== 'function') return undefined
56	    try {
57	      return new Prepared(intent, freeze(previewIntent(intent)), prompt)
58	    } catch {
59	      return undefined
60	    }
61	  }
62	  cancel(): void {
63	    this.#controller.abort()
64	  }
65	  release(): void {
66	    this.#prompt = undefined
67	  }
68	  continueAllowed(frame: ReportFrame): boolean {
69	    if (!this.#controller.signal.aborted) return true
70	    block(frame, 'invalid-input')
71	    frame.remote = { ...frame.remote, status: 'not-attempted', sendAttempted: false }
72	    frame.view = { source: 'none' }
73	    return false
74	  }
75	  async complete(
76	    frame: ReportFrame,
77	    endpoint: string,
78	    source: ActionPreview['source'],
79	  ): Promise<ActionInput | undefined> {
80	    // A preparation observation is not the target outcome.
81	    const stopped = (): undefined => {
82	      frame.remote = { ...frame.remote, status: 'not-attempted', sendAttempted: false }
83	      frame.view = { source: 'none' }
84	      return undefined
85	    }
86	    if (this.#controller.signal.aborted) {
87	      block(frame, 'invalid-input')
88	      return stopped()
89	    }
90	    const preview = freeze({
91	      intent: this.#preview,
92	      origin: frame.origin,
93	      endpoint: this.#preview.action === 'configure' ? this.#preview.endpoint : endpoint,
94	      source,
95	    })
96	    if (!validPreview(preview)) {
97	      defect(frame, 'input')
98	      return stopped()
99	    }
100	    let result: ReturnType<typeof capturePrompt>
101	    try {
102	      const returned = await this.#prompt!(preview, this.#controller.signal)
103	      result = capturePrompt(this.intent, returned)
104	    } catch {
105	      defect(frame, 'input')
106	      return stopped()
107	    } finally {
108	      this.release()
109	    }
110	    if (this.#controller.signal.aborted || result === undefined || result.kind === 'cancelled') {
111	      block(frame, 'invalid-input')
112	      return stopped()
113	    }
114	    const intent = this.intent
115	    const input = captureAction(
116	      'payload' in intent
117	        ? { ...intent, payload: { ...intent.payload, ...result.secrets } }
118	        : intent,
119	    )
120	    if (input === undefined) {
121	      block(frame, 'invalid-input')
122	      return stopped()
123	    }
124	    return input
125	  }
126	}
