7	export async function readInputFile(
8	  path: string,
9	  limit: number,
10	  secret: boolean,
11	  signal: AbortSignal,
12	): Promise<string> {
13	  if (signal.aborted) throw new InputFailure('input-cancelled')
14	  let file
15	  try {
16	    file = await open(
17	      path,
18	      constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK | constants.O_NOCTTY,
19	    )
20	  } catch {
21	    throw new InputFailure(secret ? 'secret-source' : 'input-unavailable')
22	  }
23	  try {
24	    const stat = await file.stat()
25	    if (!stat.isFile()) throw new InputFailure(secret ? 'secret-source' : 'input-unavailable')
26	    if (secret && (stat.uid !== process.geteuid!() || (stat.mode & 0o077) !== 0))
27	      throw new InputFailure('secret-permissions')
28	    if (stat.size > limit) throw new InputFailure('input-too-large')
29	    const chunks: Buffer[] = []
30	    let total = 0
31	    for (;;) {
32	      if (signal.aborted) throw new InputFailure('input-cancelled')
33	      const buffer = Buffer.alloc(Math.min(8192, limit + 1 - total))
34	      const { bytesRead } = await file.read(buffer, 0, buffer.length, null)
35	      if (bytesRead === 0) break
36	      total += bytesRead
37	      if (total > limit) throw new InputFailure('input-too-large')
38	      chunks.push(buffer.subarray(0, bytesRead))
39	    }
40	    if (signal.aborted) throw new InputFailure('input-cancelled')
41	    const bytes = Buffer.concat(chunks)
42	    if (!secret && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf)
43	      throw new InputFailure('invalid-encoding')
44	    try {
45	      return new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes)
46	    } catch {
47	      throw new InputFailure('invalid-encoding')
48	    }
49	  } catch (error) {
50	    if (error instanceof InputFailure) throw error
51	    throw new InputFailure('input-unavailable')
52	  } finally {
53	    // A rejected close is a defect, not a normal invalid-input/cancelled result.
54	    try {
55	      await file.close()
56	    } catch {
57	      throw new Error('input-restore-failed')
58	    }
59	  }
60	}
