62	/** CQ1 JSON syntax: duplicate keys and non-integer numeric spellings are rejected before rounding. */
63	export function payloadJSON(text: string): Record<string, unknown> {
64	  let at = 0
65	  const fail = (): never => {
66	    throw new InputFailure('invalid-json')
67	  }
68	  const space = () => {
69	    while (/^[\x20\x09\x0a\x0d]$/.test(text[at] ?? '')) at++
70	  }
71	  const string = (): string => {
72	    const start = at++
73	    while (at < text.length) {
74	      const char = text[at++]
75	      if (char === '\\') {
76	        at++
77	        continue
78	      }
79	      if (char === '"') {
80	        try {
81	          return JSON.parse(text.slice(start, at)) as string
82	        } catch {
83	          return fail()
84	        }
85	      }
86	    }
87	    return fail()
88	  }
89	  const value = (depth: number): unknown => {
90	    if (depth > 64) return fail()
91	    space()
92	    if (text[at] === '"') return string()
93	    if (text[at] === '{') {
94	      at++
95	      space()
96	      const result: Record<string, unknown> = Object.create(null),
97	        keys = new Set<string>()
98	      if (text[at] === '}') {
99	        at++
100	        return result
101	      }
102	      for (;;) {
103	        space()
104	        if (text[at] !== '"') return fail()
105	        const key = string()
106	        if (keys.has(key)) return fail()
107	        keys.add(key)
108	        space()
109	        if (text[at++] !== ':') return fail()
110	        result[key] = value(depth + 1)
111	        space()
112	        const end = text[at++]
113	        if (end === '}') return result
114	        if (end !== ',') return fail()
115	      }
116	    }
117	    if (text[at] === '[') {
118	      at++
119	      space()
120	      const result: unknown[] = []
121	      if (text[at] === ']') {
122	        at++
123	        return result
124	      }
125	      for (;;) {
126	        result.push(value(depth + 1))
127	        space()
128	        const end = text[at++]
129	        if (end === ']') return result
130	        if (end !== ',') return fail()
131	      }
132	    }
133	    for (const [word, result] of [
134	      ['true', true],
135	      ['false', false],
136	      ['null', null],
137	    ] as const) {
138	      if (text.startsWith(word, at)) {
139	        at += word.length
140	        return result
141	      }
142	    }
143	    const literal = /^-?(?:0|[1-9][0-9]*)/.exec(text.slice(at))?.[0]
144	    if (literal === undefined) return fail()
145	    at += literal.length
146	    const number = Number(literal)
147	    if (!Number.isSafeInteger(number)) return fail()
148	    return number
149	  }
150	  const result = value(0)
151	  space()
152	  if (at !== text.length || result === null || typeof result !== 'object' || Array.isArray(result))
153	    return fail()
154	  return result as Record<string, unknown>
155	}
