157	export async function buildIntent(
158	  invocation: Extract<Invocation, { kind: 'command' }>,
159	  signal: AbortSignal,
160	): Promise<unknown> {
161	  const { command, values } = invocation
162	  const action = command.action
163	  if (action === 'configure') {
164	    const trust =
165	      values['system-ca'] === true
166	        ? { mode: 'ca' }
167	        : values['spki'] !== undefined
168	          ? { mode: 'spki', sha256: values['spki'] }
169	          : {
170	              mode: 'ca',
171	              certificateAuthorities: await readInputFile(
172	                values['ca-file'] as string,
173	                1024 * 1024,
174	                false,
175	                signal,
176	              ),
177	            }
178	    return { action, endpoint: values['endpoint'], trust }
179	  }
180	  if (action === 'health' || action === 'logout') return { action }
181	  const payload =
182	    values['payload-file'] === undefined
183	      ? {}
184	      : payloadJSON(await readInputFile(values['payload-file'] as string, 64 * 1024, false, signal))
185	  for (const field of command.secretFields)
186	    if (Object.hasOwn(payload, field)) throw new InputFailure('secret-source')
187	  if (values['login-identifier'] !== undefined) {
188	    if (Object.hasOwn(payload, 'loginIdentifier')) throw new InputFailure('invalid-options')
189	    payload['loginIdentifier'] = values['login-identifier']
190	  }
191	  return {
192	    action,
193	    payload,
194	    ...(action === 'invoke'
195	      ? { operation: command.operation, ...(values['refresh'] ? { readMode: 'refresh' } : {}) }
196	      : {}),
197	  }
198	}
199	export async function readSecrets(
200	  invocation: Extract<Invocation, { kind: 'command' }>,
201	  signal: AbortSignal,
202	): Promise<PromptResult> {
203	  for (const field of invocation.command.secretFields) {
204	    if (typeof invocation.values[secretOption(field)] !== 'string')
205	      throw new InputFailure('tty-unsupported')
206	  }
207	  const secrets: Record<string, string> = {}
208	  for (const field of invocation.command.secretFields) {
209	    const path = invocation.values[secretOption(field)]
210	    if (typeof path !== 'string') throw new InputFailure('tty-unsupported')
211	    secrets[field] = await readInputFile(path, 64 * 1024, true, signal)
212	  }
213	  return {
214	    kind: 'continue',
215	    secrets:
216	      secrets['credential'] !== undefined
217	        ? { credential: secrets['credential'] }
218	        : secrets['currentCredential'] !== undefined
219	          ? {
220	              currentCredential: secrets['currentCredential'],
221	              newCredential: secrets['newCredential']!,
222	            }
223	          : {},
224	  }
225	}
