32	const inputSchema = ajv.compile({ $ref: `${cg.$id}#/$defs/Input` })
33	const outputSchema = ajv.compile({ $ref: `${cg.$id}#/$defs/Output` })
34	const instantSchema = ajv.compile({ $ref: `${oe.$id}#/$defs/Instant` })
