36	function capture<T>(input: unknown, valid: (value: unknown) => boolean): T | undefined {
37	  let text: string | undefined
38	  try {
39	    text = JSON.stringify(input)
40	  } catch {
41	    return undefined
42	  }
43	  if (text === undefined) return undefined
44	  const copy: unknown = JSON.parse(text)
45	  try {
46	    if (!valid(input) || !valid(copy)) return undefined
47	  } catch {
48	    return undefined
49	  }
50	  return freeze(copy) as T
51	}
52	export function captureAction(input: unknown): ActionInput | undefined {
53	  return capture<ActionInput>(input, inputSchema)
54	}
55	export function captureIntent(input: unknown): ActionIntent | undefined {
56	  return capture<ActionIntent>(input, intentSchema)
57	}
58	export function capturePrompt(intent: ActionIntent, result: unknown): PromptResult | undefined {
59	  return capture<{ intent: ActionIntent; result: PromptResult }>({ intent, result }, promptSchema)
60	    ?.result
61	}
62	export function validPreview(value: unknown): value is ActionPreview {
63	  return previewSchema(value)
64	}
65	export function validReport(value: unknown): boolean {
66	  return outputSchema(value)
67	}
68	export function validInstant(value: unknown): value is string {
69	  return instantSchema(value)
70	}
71	export function object(value: unknown): value is Record<string, unknown> {
72	  return value !== null && typeof value === 'object' && !Array.isArray(value)
73	}
74	export function freeze<T>(value: T): T {
75	  if (value !== null && typeof value === 'object') {
76	    for (const item of Object.values(value)) freeze(item)
77	    Object.freeze(value)
78	  }
79	  return value
80	}
81	/** Values are already captured JSON; this is structural equality, not identity normalization. */
82	export function canonical(value: unknown): string {
83	  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`
84	  if (object(value))
85	    return `{${Object.keys(value)
86	      .sort()
87	      .map(k => `${JSON.stringify(k)}:${canonical(value[k])}`)
88	      .join(',')}}`
89	  return JSON.stringify(value) ?? 'undefined'
90	}
