1	import { constants } from 'node:fs'
2	import { open } from 'node:fs/promises'
3	import { HOST_VERSION } from './version.ts'
4	
5	export async function readBuildId(
6	  marker = new URL('../BUILD_ID', import.meta.url),
7	): Promise<string | null> {
8	  let file
9	  try {
10	    file = await open(marker, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK)
11	  } catch (error) {
12	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null
13	    throw new Error('invalid-build-id')
14	  }
15	  try {
16	    const stat = await file.stat()
17	    if (!stat.isFile() || stat.size < 64 || stat.size > 65) throw new Error('invalid-build-id')
18	    const buffer = Buffer.alloc(66)
19	    const { bytesRead } = await file.read(buffer, 0, buffer.length, 0)
20	    const value = buffer.subarray(0, bytesRead).toString('latin1')
21	    if (!/^[0-9a-f]{64}\n?$/.test(value)) throw new Error('invalid-build-id')
22	    return value.trimEnd()
23	  } finally {
24	    await file.close()
25	  }
26	}
27	export async function buildVersionText(marker?: URL): Promise<string> {
28	  return `tenancy-host ${HOST_VERSION} ${(await readBuildId(marker)) ?? 'development'}\n`
29	}
30	interface VersionIo {
31	  stdout(text: string): Promise<void>
32	  stderr(text: string): Promise<void>
33	}
34	export async function printBuildVersion(io: VersionIo, marker?: URL): Promise<number> {
35	  try {
36	    await io.stdout(await buildVersionText(marker))
37	    return 0
38	  } catch {
39	    try {
40	      await io.stderr('tenancy-host: version unavailable\n')
41	    } catch {
42	      // A broken diagnostic stream cannot turn the original failure into success.
43	    }
44	    return 1
45	  }
46	}
