1	import { StdinBuffer } from '@earendil-works/pi-tui'
2	import { FIELD_LIMIT, validFieldText } from './forms.ts'
3	
4	export type TerminalInput =
5	  | { readonly kind: 'key' | 'paste'; readonly text: string }
6	  | { readonly kind: 'mode'; readonly value: number }
7	  | { readonly kind: 'invalid' | 'eof' | 'input-error' | 'output-error' }
8	const START = '\x1b[200~',
9	  END = '\x1b[201~'
10	const ordinary = new Set([
11	  '\x1b[A',
12	  '\x1b[B',
13	  '\x1b[C',
14	  '\x1b[D',
15	  '\x1b[H',
16	  '\x1b[F',
17	  '\x1bOH',
18	  '\x1bOF',
19	  '\x1b[1~',
20	  '\x1b[4~',
21	  '\x1b[3~',
22	  '\x1b[5~',
23	  '\x1b[6~',
24	])
25	const decoder = () => new TextDecoder('utf-8', { fatal: true, ignoreBOM: true })
26	
27	/** Owns framing before the library sees any bytes; never feeds it paste bodies. */
28	export class InputFramer {
29	  readonly #emit: (event: TerminalInput) => void
30	  readonly #keys = new StdinBuffer()
31	  #decoder = decoder()
32	  #escape = ''
33	  #discard: 'csi' | 'string' | undefined
34	  #stringEscape = false
35	  #paste = false
36	  #tail = ''
37	  #text = ''
38	  #bytes = 0
39	  #invalid = false
40	  #stopping = false
41	  #pendingStart = false
42	  #ended = false
43	  #done = Promise.withResolvers<void>()
44	  constructor(emit: (event: TerminalInput) => void) {
45	    this.#emit = emit
46	    this.#keys.on('data', text => {
47	      if (!this.#stopping) this.#emit({ kind: 'key', text })
48	    })
49	  }
50	  get inPaste(): boolean {
51	    return this.#paste
52	  }
53	  get bufferedBytes(): number {
54	    return Buffer.byteLength(this.#text) + this.#tail.length + this.#escape.length
55	  }
56	  feed(bytes: Uint8Array): void {
57	    if (this.#ended) return
58	    for (const byte of bytes) {
59	      if (this.#paste) this.#pasteByte(byte)
60	      else this.#ordinaryByte(byte)
61	    }
62	  }
63	  #resetDecoder(): void {
64	    this.#decoder = decoder()
65	  }
66	  #finishText(): boolean {
67	    try {
68	      this.#decoder.decode()
69	      return true
70	    } catch {
71	      return false
72	    } finally {
73	      this.#resetDecoder()
74	    }
75	  }
76	  #ordinaryByte(byte: number): void {
77	    if (this.#discard === 'csi') {
78	      if (byte >= 0x40 && byte <= 0x7e) this.#discard = undefined
79	      return
80	    }
81	    if (this.#discard === 'string') {
82	      if (byte === 7 || (this.#stringEscape && byte === 92)) this.#discard = undefined
83	      this.#stringEscape = byte === 27
84	      return
85	    }
86	    if (this.#escape !== '' && (byte === 3 || byte === 7)) {
87	      // An actual C0 byte cannot continue a paste-begin or mode-reply prefix.
88	      // A lone Escape itself never times out into a semantic cancellation.
89	      this.#escape = ''
90	      if (this.#pendingStart) {
91	        this.#pendingStart = false
92	        this.#done.resolve()
93	      }
94	      if (!this.#stopping) this.#emit({ kind: 'key', text: String.fromCharCode(byte) })
95	      return
96	    }
97	    if (this.#escape !== '') {
98	      this.#escape += String.fromCharCode(byte)
99	      if (this.#escape.length > 64 || byte > 127) {
100	        if (this.#escape.startsWith('\x1b[') && !(byte >= 0x40 && byte <= 0x7e))
101	          this.#discard = 'csi'
102	        this.#escape = ''
103	        this.#bad()
104	        if (this.#pendingStart) {
105	          this.#pendingStart = false
106	          this.#done.resolve()
107	        }
108	        return
109	      }
110	      const prefix = this.#escape
111	      if (prefix.length === 2 && [93, 80, 94, 95, 88].includes(byte)) {
112	        this.#escape = ''
113	        this.#discard = 'string'
114	        this.#stringEscape = false
115	        this.#bad()
116	        if (this.#pendingStart) {
117	          this.#pendingStart = false
118	          this.#done.resolve()
119	        }
120	        return
121	      }
122	      // Only CSI/SS3 sequences are accepted. No OSC, mouse, Kitty or Alt text.
123	      if (prefix.length === 2 && (byte === 91 || byte === 79)) {
124	        return
125	      }
126	      if (prefix.length === 2 || (byte >= 0x40 && byte <= 0x7e)) {
127	        this.#escape = ''
128	        if (prefix === START) {
129	          if (this.#stopping && !this.#pendingStart) return
130	          this.#pendingStart = false
131	          this.#paste = true
132	          this.#text = ''
133	          this.#tail = ''
134	          this.#bytes = 0
135	          this.#invalid = this.#stopping
136	          this.#resetDecoder()
137	        } else {
138	          if (this.#pendingStart) {
139	            this.#pendingStart = false
140	            this.#done.resolve()
141	          }
142	          const mode = /^\x1b\[\?2004;([0-4])\$y$/.exec(prefix)
143	          if (mode) this.#emit({ kind: 'mode', value: Number(mode[1]) })
144	          else if (ordinary.has(prefix)) {
145	            if (!this.#stopping) this.#keys.process(prefix)
146	          } else this.#bad()
147	        }
148	      }
149	      return
150	    }
151	    if (byte === 27) {
152	      if (!this.#finishText()) this.#bad()
153	      this.#escape = '\x1b'
154	      return
155	    }
156	    try {
157	      const text = this.#decoder.decode(Uint8Array.of(byte), { stream: true })
158	      // StdinBuffer extracts ordinary text by UTF16 code unit. The strict decoder
159	      // already delivers a complete scalar; do not split supplementary characters.
160	      if (text && !this.#stopping) {
161	        if (text.length === 2) this.#emit({ kind: 'key', text })
162	        else this.#keys.process(text)
163	      }
164	    } catch {
165	      this.#resetDecoder()
166	      this.#bad()
167	    }
168	  }
169	  #bad(): void {
170	    if (!this.#stopping) this.#emit({ kind: 'invalid' })
171	  }
172	  error(): void {
173	    // A stream error is not EOF and cannot settle an owned partial frame.
174	    this.#emit({ kind: 'input-error' })
175	  }
176	  #pasteByte(byte: number): void {
177	    this.#tail += String.fromCharCode(byte)
178	    while (!END.startsWith(this.#tail)) {
179	      const first = this.#tail.charCodeAt(0)
180	      this.#tail = this.#tail.slice(1)
181	      this.#bytes = Math.min(FIELD_LIMIT + 1, this.#bytes + 1)
182	      if (this.#bytes > FIELD_LIMIT) this.#invalid = true
183	      if (!this.#invalid) {
184	        try {
185	          this.#text += this.#decoder.decode(Uint8Array.of(first), { stream: true })
186	        } catch {
187	          this.#invalid = true
188	        }
189	      }
190	      if (this.#invalid) this.#text = ''
191	    }
192	    if (this.#tail !== END) return
193	    const text = this.#text
194	    const valid = this.#finishText() && !this.#invalid && validFieldText(text)
195	    this.#paste = false
196	    this.#tail = ''
197	    this.#text = ''
198	    this.#bytes = 0
199	    if (this.#stopping) this.#done.resolve()
200	    else if (valid) this.#emit({ kind: 'paste', text })
201	    else this.#bad()
202	  }
203	  /** Stop new semantic input; the owner still feeds bytes until the old paste actually ends. */
204	  stop(): Promise<void> {
205	    this.#stopping = true
206	    this.#keys.clear()
207	    if (this.#paste) {
208	      this.#invalid = true
209	      this.#text = ''
210	    } else {
211	      if (this.#escape !== '' && START.startsWith(this.#escape)) this.#pendingStart = true
212	      else {
213	        this.#escape = ''
214	        this.#done.resolve()
215	      }
216	    }
217	    return this.#done.promise
218	  }
219	  eof(): void {
220	    if (this.#ended) return
221	    this.#ended = true
222	    if (!this.#finishText() || this.#paste || this.#escape !== '') this.#bad()
223	    this.#paste = false
224	    this.#tail = ''
225	    this.#text = ''
226	    this.#escape = ''
227	    this.#keys.destroy()
228	    this.#done.resolve()
229	    this.#emit({ kind: 'eof' })
230	  }
231	  dispose(): void {
232	    if ((this.#paste || this.#pendingStart) && !this.#ended) throw new Error('input still owned')
233	    this.#ended = true
234	    this.#keys.destroy()
235	    this.#done.resolve()
236	  }
237	}
